import type { WarrantyCurrent, WarrantyDetails, WarrantyInput, WarrantyRevision } from '../../src/utils/manualWarrantyWorkspace'
import type { MetadataContext, MetadataInput } from '../../src/utils/assetMetadataWorkspace'
export const id = (n: number) => `55000000-0000-4000-8000-${n.toString(16).padStart(12, '0')}`
export const context: MetadataContext = { tenantId: id(1), assetId: id(2), actorId: id(3), permissionVersion: 1, canWrite: true }
export const input = (): WarrantyInput => ({ warranty_start: '2026-01-01', warranty_expiry: '2027-01-01', warranty_supplier: '明确供应商😀', overdue_service_date: null, note: '明确资产资料备注' })
export const metadata = (): MetadataInput => ({ name: '虚构资料', type: 'router', site_id: 'site-a', brand: null, model: null, serial_number: null, location: null, owner_id: null, business_description: null, purchase_date: null, warranty_expiry: input().warranty_expiry, overdue_service_date: null, collection_method_note: null, note: input().note })
export const details = (): WarrantyDetails => ({ warranty_start: input().warranty_start, warranty_supplier: input().warranty_supplier })
export const current = (v = 1, d: WarrantyDetails | null = v > 1 ? details() : null): WarrantyCurrent => ({ asset: { id: context.assetId, tenant_id: context.tenantId, name: metadata().name, type: 'router', management_ip: '192.0.2.1', site_id: 'site-a', source: 'manual', status: 'unknown', lifecycle_status: 'DRAFT', sampled_at: null, unknown_reason: 'NOT_ONBOARDED', availability: 'UNKNOWN', sync_state: 'PENDING_ONBOARDING', version: v, created_at: '2026-10-03T00:00:00Z', updated_at: '2026-10-03T00:00:00Z' }, metadata: v > 1 ? metadata() : null, metadata_version: v > 1 ? v : null, recorded_by: v > 1 ? context.actorId : null, recorded_at: v > 1 ? '2026-10-03T00:00:00Z' : null, can_edit: true, edit_blockers: [], scope: 'INTERNAL_MANUAL_DRAFT', verification_status: v > 1 ? 'SELF_REPORTED' : null, source: 'postgresql', monitoring_applied: false, cmdb_applied: false, management_ip_change_status: 'CONFIG_PENDING', warranty_details: d, warranty_coverage_verified: false, warranty_supplier_verification: 'UNVERIFIED' })
export const revision = (v: number): WarrantyRevision => { const before = current(v - 1); return { asset_version: v, previous_metadata_version: before.metadata_version, actor_id: context.actorId, recorded_at: '2026-10-03T00:00:00Z', before: { asset: before.asset, metadata: before.metadata, metadata_version: before.metadata_version, warranty_details: before.warranty_details }, metadata: metadata(), management_ip: '192.0.2.1', verification_status: 'SELF_REPORTED', monitoring_applied: false, cmdb_applied: false, warranty_details: details(), warranty_coverage_verified: false, warranty_supplier_verification: 'UNVERIFIED' } }
export const history = (v = 1) => ({ items: Array.from({ length: v - 1 }, (_, i) => revision(v - i)), has_more: false, next_before_version: null, source: 'postgresql', scope: 'INTERNAL_MANUAL_DRAFT', page_size_limit: 100 })
